using System;using System.Linq;using System.Drawing;using System.Windows.Forms;
sealed partial class Companion {
 internal void AttachReadingMenu(FormattedPage reader,RichTextBox source,Action changed){var menu=new ContextMenuStrip();reader.ContextMenuStrip=menu;menu.Opening+=(s,e)=>{menu.Items.Clear();menu.Items.Add("Copy selected text",null,(a,b)=>reader.Copy()).Enabled=reader.SelectionLength>0;menu.Items.Add("Select all",null,(a,b)=>reader.SelectAll());var formatMenu=new ToolStripMenuItem("Format selection");var inner=new ContextMenuStrip();int first=reader.SourceLineAt(reader.SelectionStart),last=reader.SourceLineAt(reader.SelectionStart+reader.SelectionLength);int start=source.GetFirstCharIndexFromLine(first),end=source.GetFirstCharIndexFromLine(last+1);if(start<0)start=0;if(end<0)end=source.TextLength;source.Select(start,Math.Max(0,end-start));if(reader.SelectionLength>0){int found=source.Text.IndexOf(reader.SelectedText.TrimEnd('\r','\n'),start,StringComparison.Ordinal);if(found>=start&&found<end)source.Select(found,reader.SelectedText.TrimEnd('\r','\n').Length);}AddFormatting(inner,source);foreach(ToolStripItem item in inner.Items.Cast<ToolStripItem>().ToArray())formatMenu.DropDownItems.Add(item);inner.Dispose();foreach(ToolStripMenuItem item in formatMenu.DropDownItems.OfType<ToolStripMenuItem>()){if(item.HasDropDownItems)foreach(ToolStripMenuItem child in item.DropDownItems.OfType<ToolStripMenuItem>())child.Click+=(a,b)=>changed();else item.Click+=(a,b)=>changed();}menu.Items.Add(formatMenu);CompanionPalette.Apply(menu,store.Pref.Theme);PreparePopup(menu);};reader.Disposed+=(s,e)=>menu.Dispose();}
 internal void SetupResponsiveStrips(){foreach(var strip in new[]{top,quick,viewTools,format}){var popup=strip.OverflowButton.DropDown;popup.Opening+=(s,e)=>{CompanionPalette.Apply(popup,store.Pref.Theme);};}Action refresh=()=>{bool narrow=ClientSize.Width<650;if(allNotesTab!=null){allNotesTab.Text="All notes";currentNoteTab.Text=ClientSize.Width<440?"Page":"Current note";currentNoteTab.ToolTipText="Current note · focus on this page";}if(brandItem!=null)brandItem.Text=narrow?"Jago":"Jago Companion";top.Padding=new Padding(8,4,IsTabbed||FormBorderStyle!=FormBorderStyle.None?8:108,4);foreach(var strip in new[]{top,quick,viewTools,format}){strip.PerformLayout();strip.OverflowButton.ToolTipText="More actions";strip.OverflowButton.DropDown.AutoSize=true;strip.OverflowButton.DropDown.Font=Font;}};Resize+=(s,e)=>refresh();Shown+=(s,e)=>refresh();}
}
